<script setup lang="ts">import { computed, onMounted, provide, ref } from "vue"; import { useRoute } from "vue-router"; import { listItems, type Item } from "../api"; const route = useRoute(); const storeId = String(route.query.storeId ?? ""); const item = ref<Item | null>(null); provide("inventoryItem", item); provide("inventoryStoreId", storeId); const title = computed(() => item.value?.name ?? "Material"); onMounted(async () => { item.value = (await listItems(storeId || undefined)).find((entry) => entry.id === route.params.id) ?? null; });</script><template><section v-if="item" class="customer-detail"><p class="breadcrumb"><RouterLink :to="{ name: 'inventory.list', query: storeId ? { storeId } : {} }">Almacen</RouterLink> / {{ title }}</p><header><div><p class="eyebrow">Material</p><h1>{{ title }}</h1><span class="status-pill">{{ item.stock }} {{ item.unit }}</span></div></header><nav class="tab-nav"><RouterLink :to="{ name: 'inventory.detail.general', query: storeId ? { storeId } : {} }">General</RouterLink><RouterLink :to="{ name: 'inventory.detail.movements', query: storeId ? { storeId } : {} }">Movimientos</RouterLink></nav><RouterView /></section><p v-else class="empty">Cargando material...</p></template>